import React, { useState } from 'react';
import { Link } from 'react-router-dom';
import './JsonFormatter.css';

const JsonFormatter = () => {
  const [input, setInput] = useState('');
  const [output, setOutput] = useState('');
  const [error, setError] = useState('');
  const [indentSize, setIndentSize] = useState(2);

  const formatJson = () => {
    try {
      const parsed = JSON.parse(input);
      const formatted = JSON.stringify(parsed, null, indentSize);
      setOutput(formatted);
      setError('');

      // Scroll to top to show results
      setTimeout(() => {
        window.scrollTo({ top: 0, behavior: 'smooth' });
      }, 100);
    } catch (e) {
      setError('Invalid JSON: ' + e.message);
      setOutput('');
    }
  };

  const minifyJson = () => {
    try {
      const parsed = JSON.parse(input);
      const minified = JSON.stringify(parsed);
      setOutput(minified);
      setError('');

      // Scroll to top to show results
      setTimeout(() => {
        window.scrollTo({ top: 0, behavior: 'smooth' });
      }, 100);
    } catch (e) {
      setError('Invalid JSON: ' + e.message);
      setOutput('');
    }
  };

  const clearAll = () => {
    setInput('');
    setOutput('');
    setError('');
  };

  const copyToClipboard = () => {
    navigator.clipboard.writeText(output);
  };

  return (
    <div className="json-formatter-page">
      <div className="json-header">
        <Link to="/" className="back-button">← Back to Home</Link>
        <h1>JSON Formatter</h1>
        <p>Format and validate JSON data</p>
      </div>

      <div className="json-container">
        {output && (
          <div className="output-section">
            <div className="output-header">
              <h2>Formatted Result</h2>
              <button onClick={copyToClipboard} className="copy-button">
                Copy to Clipboard
              </button>
            </div>
            <div className="output-box">
              <pre className="json-output">{output}</pre>
            </div>
          </div>
        )}

        {error && (
          <div className="error-section">
            <div className="error-message">❌ {error}</div>
          </div>
        )}

        <div className="input-section">
          <div className="controls-row">
            <h3>Input JSON</h3>
            <div className="indent-control">
              <label>Indent Size:</label>
              <select value={indentSize} onChange={(e) => setIndentSize(Number(e.target.value))}>
                <option value={2}>2 spaces</option>
                <option value={4}>4 spaces</option>
                <option value={8}>8 spaces</option>
              </select>
            </div>
          </div>
          <textarea
            value={input}
            onChange={(e) => setInput(e.target.value)}
            placeholder='Paste your JSON here... e.g. {"name":"John","age":30}'
            className="json-textarea"
          />
          <div className="button-group">
            <button onClick={formatJson} className="format-button">
              Format JSON
            </button>
            <button onClick={minifyJson} className="minify-button">
              Minify JSON
            </button>
            <button onClick={clearAll} className="clear-button">
              Clear All
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

export default JsonFormatter;
